bool saveBmp(const RECT&r,const fs::path&p){int w=r.right-r.left,h=r.bottom-r.top;if(w<1||h<1||!st.bmp)return false;HDC s=GetDC(nullptr),m=CreateCompatibleDC(s),src=CreateCompatibleDC(s);auto os=SelectObject(src,st.bmp);HBITMAP b=CreateCompatibleBitmap(s,w,h);auto om=SelectObject(m,b);BitBlt(m,0,0,w,h,src,r.left,r.top,SRCCOPY);SelectObject(src,os);SelectObject(m,om);BITMAPINFO bi{};bi.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);bi.bmiHeader.biWidth=w;bi.bmiHeader.biHeight=-h;bi.bmiHeader.biPlanes=1;bi.bmiHeader.biBitCount=32;std::vector<unsigned char> px((size_t)w*h*4);GetDIBits(s,b,0,h,px.data(),&bi,DIB_RGB_COLORS);BITMAPFILEHEADER fh{};fh.bfType=0x4d42;fh.bfOffBits=sizeof(fh)+sizeof(BITMAPINFOHEADER);fh.bfSize=fh.bfOffBits+(DWORD)px.size();std::ofstream o(p,std::ios::binary);o.write((char*)&fh,sizeof fh);o.write((char*)&bi.bmiHeader,sizeof bi.bmiHeader);o.write((char*)px.data(),px.size());DeleteObject(b);DeleteDC(src);DeleteDC(m);ReleaseDC(nullptr,s);return o.good();}
std::wstring ocr(const fs::path& image){try{auto md=ocrCache()/L"ppocrv6_tiny";const wchar_t*n[]={L"PP_OCRv6_tiny_det.param",L"PP_OCRv6_tiny_det.bin",L"PP_OCRv6_tiny_rec.param",L"PP_OCRv6_tiny_rec.bin",L"PP_LCNet_x0_25_textline_ori.param",L"PP_LCNet_x0_25_textline_ori.bin",L"ppocr_keys_v6.txt"};for(auto x:n)if(!fs::exists(md/x))return L"PP-OCRv6 模型文件缺失："+std::wstring(x);cv::Mat mat=cv::imread(image.string());if(mat.empty())return L"无法读取截图";OCR::OCREngine e;if(!e.Initialize((ocrCache()/L"ppocrv6_config.json").string()))return L"PP-OCRv6 模型加载失败";auto rs=e.Run(mat);struct I{const OCR::OCRResult*r;int l,rr,t,b,y;};std::vector<I> a;for(auto&x:rs){if(x.line.text.empty()||x.box.points.empty())continue;int l=x.box.points[0].x,rr=l,t=x.box.points[0].y,b=t;for(auto&p:x.box.points){l=(std::min)(l,p.x);rr=(std::max)(rr,p.x);t=(std::min)(t,p.y);b=(std::max)(b,p.y);}a.push_back({&x,l,rr,t,b,(t+b)/2});}std::sort(a.begin(),a.end(),[](const I&x,const I&y){int h=(std::max)(x.b-x.t,y.b-y.t);return std::abs(x.y-y.y)<=h/2?x.l<y.l:x.y<y.y;});std::string s;int pr=-1,ph=0,py=-1;for(auto&x:a){int h=(std::max)(1,x.b-x.t);if(!s.empty()){if(py>=0&&std::abs(x.y-py)>(std::max)(h,ph)/2)s+="\n";else if(x.l-pr>h/3)s+=" ";}s+=x.r->line.text;pr=x.rr;ph=h;py=x.y;}if(s.empty())s="未识别到文字";int z=MultiByteToWideChar(CP_UTF8,0,s.data(),(int)s.size(),nullptr,0);std::wstring w(z,L' ');MultiByteToWideChar(CP_UTF8,0,s.data(),(int)s.size(),w.data(),z);return w;}catch(...){return L"PP-OCRv6 识别发生异常";}}
std::wstring displayText(const std::wstring& text){std::wstring out;out.reserve(text.size()+16);for(size_t i=0;i<text.size();++i){if(text[i]==L"\\"[0]&&i+1<text.size()&&text[i+1]==L"n"[0]){out+=L"\r\n";++i;continue;}if(text[i]==L"\r"[0]){if(i+1<text.size()&&text[i+1]==L"\n"[0])++i;out+=L"\r\n";continue;}if(text[i]==L"\n"[0]){out+=L"\r\n";continue;}out+=text[i];}return out;}
std::string jsonEscape(const std::wstring&s){int n=WideCharToMultiByte(CP_UTF8,0,s.data(),(int)s.size(),nullptr,0,nullptr,nullptr);std::string u(n,'\0');WideCharToMultiByte(CP_UTF8,0,s.data(),(int)s.size(),u.data(),n,nullptr,nullptr);std::string o;const char hex[]="0123456789abcdef";for(unsigned char c:u){if(c=='\\'||c=='"'){o+='\\';o+=c;}else if(c=='\b')o+="\\b";else if(c=='\f')o+="\\f";else if(c=='\n')o+="\\n";else if(c=='\r')o+="\\r";else if(c=='\t')o+="\\t";else if(c<0x20){o+="\\u00";o+=hex[c>>4];o+=hex[c&15];}else o+=c;}return o;}
std::wstring utf8(const std::string&s);
std::wstring jsonResult(const std::string& raw){auto key=raw.find("\"result\"");if(key==std::string::npos)return L"";auto colon=raw.find(':',key+8);auto begin=colon==std::string::npos?std::string::npos:raw.find('"',colon+1);if(begin==std::string::npos)return L"";std::string value;for(size_t i=begin+1;i<raw.size();++i){char c=raw[i];if(c=='"')return utf8(value);if(c!='\\'){value+=c;continue;}if(++i>=raw.size())return L"";char e=raw[i];if(e=='n')value+='\n';else if(e=='r')value+='\r';else if(e=='t')value+='\t';else if(e=='b')value+='\b';else if(e=='f')value+='\f';else if(e=='"'||e=='\\'||e=='/')value+=e;else return L"";}return L"";}
std::wstring utf8(const std::string&s){int n=MultiByteToWideChar(CP_UTF8,0,s.data(),(int)s.size(),nullptr,0);std::wstring w(n,L' ');MultiByteToWideChar(CP_UTF8,0,s.data(),(int)s.size(),w.data(),n);return w;}
std::wstring translateLocal(const std::wstring& text,const std::wstring& source,const std::wstring& target,bool retried=false){if(translationCancel.load())return L"翻译已取消";if(text.empty()||source==target)return text;if(!translatorReady()&&!startTranslator())return L"翻译引擎启动失败，请关闭程序后重新打开。";HINTERNET ses=WinHttpOpen(L"PP-OCRv6-Desktop",WINHTTP_ACCESS_TYPE_NO_PROXY,nullptr,nullptr,0);if(!ses)return L"无法启动翻译连接";WinHttpSetTimeouts(ses,3000,3000,15000,60000);HINTERNET con=WinHttpConnect(ses,L"127.0.0.1",8989,0);std::string body="{\"from\":\""+jsonEscape(source)+"\",\"to\":\""+jsonEscape(target)+"\",\"text\":\""+jsonEscape(text)+"\",\"html\":false}";HINTERNET req=con?WinHttpOpenRequest(con,L"POST",L"/translate",nullptr,nullptr,nullptr,0):nullptr;std::wstring out;DWORD status=0,statusSize=sizeof(status);if(req&&WinHttpAddRequestHeaders(req,L"Content-Type: application/json; charset=utf-8\r\n",-1,WINHTTP_ADDREQ_FLAG_ADD)&&WinHttpSendRequest(req,nullptr,0,(LPVOID)body.data(),(DWORD)body.size(),(DWORD)body.size(),0)&&WinHttpReceiveResponse(req,nullptr)){WinHttpQueryHeaders(req,WINHTTP_QUERY_STATUS_CODE|WINHTTP_QUERY_FLAG_NUMBER,nullptr,&status,&statusSize,nullptr);std::string raw;for(;;){DWORD n=0;if(!WinHttpQueryDataAvailable(req,&n)||!n)break;std::string b(n,'\0');DWORD got=0;if(!WinHttpReadData(req,b.data(),n,&got))break;raw.append(b.data(),got);}if(status>=200&&status<300)out=jsonResult(raw);if(out.empty()&&status>=400)out=L"翻译服务返回错误（HTTP "+std::to_wstring(status)+L"）。";}if(req)WinHttpCloseHandle(req);if(con)WinHttpCloseHandle(con);WinHttpCloseHandle(ses);if(!out.empty())return out;if(!retried&&!translationCancel.load()){stopTranslator();if(startTranslator())return translateLocal(text,source,target,true);}return L"翻译失败：翻译服务没有返回可用内容。";}


std::wstring translatePreserveBreaks(const std::wstring& text,const std::wstring& source,const std::wstring& target){if(text.empty())return L"";if(translationCancel.load())return L"翻译已取消";return translateLocal(text,source,target);}
